// Parse Input: extract the rug category (and optional "focus:" line) from chat or from another workflow.
// Categories come from the category_config table, so a team can add or rename one without editing this workflow.
let input = '';
for (const trigger of ['When chat message received', 'When Called by Another Workflow']) {
  try { input = $(trigger).first().json.chatInput || input; } catch (e) { /* that trigger did not run */ }
}

const categories = $input.all().map(i => i.json)
  .filter(c => c.category_key && c.active !== false)
  .map(c => ({
    key: c.category_key,
    display: c.display_name,
    patterns: String(c.patterns || '').split(',').map(p => p.trim().toLowerCase()).filter(Boolean),
    minListings: Number(c.min_listings || 10),
    notes: c.analyst_notes || ''
  }));
if (!categories.length) throw new Error('category_config has no active categories. Add at least one row with active = true.');

const lowerInput = input.toLowerCase();
let match = null;
for (const cat of categories) {
  if (cat.patterns.some(p => lowerInput.includes(p)) || lowerInput.includes(cat.key)) { match = cat; break; }
}

const focusMatch = input.match(/focus\s*:\s*([^\n]+)/i);
const focus = focusMatch ? focusMatch[1].trim() : '';

return [{
  json: {
    selectedCategory: match ? match.display : null,
    categoryDisplayName: match ? match.display : null,
    categoryKey: match ? match.key : null,
    focus,
    minListings: match ? match.minListings : 10,
    analystNotes: match ? match.notes : '',
    availableCategories: categories.map(c => c.display),
    hasValidInput: !!match,
    errorReason: match ? null : 'no_category'
  }
}];

// Error Response: explain in chat why no report was produced.
const input = $input.first().json;
const reason = input.errorReason || 'unknown';
const available = (input.availableCategories || []).join(', ');

let message;
if (reason === 'no_category') {
  message = 'I could not detect a rug category. Send one of: ' + available + '. Optionally add a second line such as "focus: washable".';
} else if (reason === 'missing_retailer_data') {
  message = 'No report was generated: the product API returned no usable products for ' + (input.missingRetailers || []).join(', ') +
    '. A competitor comparison needs Wayfair, Amazon and Walmart data. Try again in a few minutes.';
} else {
  message = 'An unknown error occurred. Check the execution log in n8n.';
}

return [{ json: { error: true, reason, output: message } }];

// Build Run Log: one row per run in agent_runs, so a run that "succeeds" with thin output
// is visible (status "degraded") instead of passing silently. The listing threshold comes from category_config.
const parsed = $('Input Parser').first().json;
const startedAt = $('Record Listings').first().json.run_date;
const finishedAt = new Date();
let trustVerdict = '';
try { trustVerdict = $('AI Evidence Check').first().json.verdict || ''; } catch (e) { trustVerdict = 'not checked'; }

const count = (nodeName, field) => ($(nodeName).first().json[field] || []).length;
const listings = {
  wayfair: count('Reshape Wayfair Response', 'wayfair_products'),
  amazon: count('Reshape Amazon Response', 'amazonProducts'),
  walmart: count('Reshape Walmart Response', 'walmartProducts')
};

// A section counts as generated only if its agent returned real content.
const SECTIONS = ['Executive Summary Generator', 'Amazon Analysis Generator', 'Comparison Generator',
  'Pricing & Whitespace Generator', 'Recommendations Generator', 'Supplier Identification Generator'];
const missing = SECTIONS.filter(name => {
  try { return String($(name).first().json.output || '').trim().length < 200; }
  catch (e) { return true; }
});

const warnings = [];
for (const [retailer, n] of Object.entries(listings)) {
  if (n === 0) warnings.push(`no ${retailer} listings`);
  else if (n < (parsed.minListings || 10)) warnings.push(`only ${n} ${retailer} listings`);
}
if (missing.length) warnings.push(`missing sections: ${missing.map(s => s.replace(' Generator', '')).join(', ')}`);

return [{
  json: {
    run_id: String($execution.id),
    workflow: 'Phase 3 - Competitor Monitoring Agent v2',
    category_key: parsed.categoryKey,
    focus: parsed.focus || '',
    started_at: startedAt,
    finished_at: finishedAt.toISOString(),
    duration_s: Math.round((finishedAt - new Date(startedAt)) / 1000),
    status: warnings.length ? 'degraded' : 'ok',
    wayfair_listings: listings.wayfair,
    amazon_listings: listings.amazon,
    walmart_listings: listings.walmart,
    sections_generated: SECTIONS.length - missing.length,
    sections_expected: SECTIONS.length,
    missing_sections: missing.map(s => s.replace(' Generator', '')).join(', '),
    warnings: warnings.join('; '),
    trust_verdict: trustVerdict
  }
}];
